    # Per line: 1.5 -> 2, 1.5 -> 2 => 4 (rounding the total 3.0 would give 3).
    assert invoice_tax(lines, 0.1) == 4


def test_invoice_tax_empty():
    assert invoice_tax([], 0.08) == 0
